import { CSS } from "./styles.js";
import { createCard, createFrame } from "./render.js";

const DATA_BASE = "data/tp/reco/";
const MAX_MORE_BATCHES = 1;
const IMPRESSION_THRESHOLD = 0.5;
const SAFETY_TIMEOUT = 100;
const CLOCK = Date.UTC(2026, 10, 2, 7, 15, 0);

const work = window.__benchmarkWork;
const config = (window.__tpConfig && window.__tpConfig.reco) || { placements: [] };
const stats = { impressions: 0, clicks: 0, bytes: 0, batches: 0 };
const frameWaiters = new Map();
let styleInjected = false;

function sink(payload) {
    stats.bytes += payload.length;
}

function ensureStyle() {
    if (styleInjected)
        return;
    styleInjected = true;
    const style = document.createElement("style");
    style.setAttribute("data-reco-style", "");
    style.textContent = CSS;
    document.head.appendChild(style);
}

function firstDelivery(observer) {
    return new Promise((resolve) => {
        observer.__resolve = resolve;
        setTimeout(resolve, SAFETY_TIMEOUT);
    });
}

function makeImpressionObserver(placement) {
    const observer = new IntersectionObserver((entries) => {
        for (const entry of entries) {
            if (!entry.isIntersecting)
                continue;
            observer.unobserve(entry.target);
            stats.impressions++;
            sink(JSON.stringify({ t: CLOCK + Math.round(performance.now()), placement, id: entry.target.dataset.recoId, ratio: Math.round(entry.intersectionRatio * 100), pos: Number(entry.target.dataset.recoPosition) }));
        }
        observer.__resolve?.();
    }, { threshold: [IMPRESSION_THRESHOLD] });
    return observer;
}

function placementConfig(id) {
    return config.placements.find((p) => p.id === id) || { id, frames: 1 };
}

function appendCards(list, cards, mode, placement, observer, offset) {
    const fragment = document.createDocumentFragment();
    cards.forEach((card, index) => {
        const element = createCard(card, mode, placement, offset + index);
        fragment.appendChild(element);
        observer.observe(element);
    });
    list.appendChild(fragment);
}

function addFrames(container, placement, count) {
    const waits = [];
    for (let i = 0; i < count; i++) {
        const kind = i === 0 ? "unit" : "measure";
        const frame = createFrame(placement, kind, i);
        const loaded = new Promise((resolve) => {
            frame.addEventListener("load", resolve);
            frameWaiters.set(`${placement}:${kind}:${i}`, resolve);
        });
        waits.push(loaded);
        container.appendChild(frame);
    }
    work?.track(Promise.all(waits));
}

function setupLoadMore(container, list, data, mode, placement, observer) {
    const more = data.more || [];
    if (!more.length)
        return;
    const sentinel = document.createElement("div");
    sentinel.className = "rc-sentinel";
    sentinel.setAttribute("aria-hidden", "true");
    container.appendChild(sentinel);
    let batches = 0;
    const loadMore = new IntersectionObserver((entries) => {
        for (const entry of entries) {
            if (!entry.isIntersecting || batches >= MAX_MORE_BATCHES)
                continue;
            batches++;
            stats.batches++;
            const start = list.children.length;
            const promise = new Promise((resolve) => {
                requestAnimationFrame(() => {
                    appendCards(list, more, mode, placement, observer, start);
                    resolve();
                });
            });
            work?.track(promise);
            loadMore.disconnect();
            sentinel.remove();
        }
    }, { rootMargin: "0px 0px 200px 0px" });
    loadMore.observe(sentinel);
}

async function mount(container) {
    const placement = container.dataset.recoPlacement;
    const mode = container.dataset.recoMode || "stream";
    if (container.dataset.recoState)
        return;
    container.dataset.recoState = "loading";
    ensureStyle();
    const response = await window.fetch(`${DATA_BASE}${placement}.json`);
    const data = await response.json();
    const root = document.createElement("div");
    root.className = `rc-root rc-${mode}`;
    const heading = document.createElement("div");
    heading.className = "rc-heading";
    heading.textContent = data.heading;
    const list = document.createElement("div");
    list.className = "rc-list";
    root.append(heading, list);
    const observer = makeImpressionObserver(placement);
    appendCards(list, data.cards, mode, placement, observer, 0);
    container.appendChild(root);
    container.addEventListener("click", (event) => {
        const card = event.target.closest?.(".rc-card");
        if (!card)
            return;
        stats.clicks++;
        sink(JSON.stringify({ t: CLOCK + Math.round(performance.now()), placement, id: card.dataset.recoId, action: "click" }));
    });
    addFrames(container, placement, placementConfig(placement).frames);
    setupLoadMore(container, list, data, mode, placement, observer);
    container.dataset.recoState = "ready";
    work?.track(firstDelivery(observer));
}

window.addEventListener("message", (event) => {
    const data = event.data && event.data.tpReco;
    if (!data)
        return;
    const resolve = frameWaiters.get(`${data.placement}:${data.kind}:${data.index}`);
    resolve?.();
});

function start() {
    const api = window.tpReco;
    const run = (container) => {
        work?.track(mount(container).catch(() => {}));
    };
    for (const container of api.queue.splice(0))
        run(container);
    api.mount = run;
    api.stats = stats;
    work?.settled("reco");
}

start();
