export function createCard(card, mode, placement, position) {
    const element = document.createElement("article");
    element.className = "rc-card";
    element.dataset.recoId = card.id;
    element.dataset.recoPosition = String(position);
    element.dataset.recoCard = placement;
    const link = document.createElement("a");
    link.className = "rc-link";
    link.href = card.url;
    link.target = "_blank";
    link.rel = "sponsored noopener";
    link.setAttribute("aria-label", card.title);
    const figure = document.createElement("div");
    figure.className = "rc-figure";
    const image = document.createElement("img");
    image.className = "rc-image";
    image.src = card.image;
    image.alt = "";
    image.width = mode === "feed" ? 240 : 160;
    image.height = mode === "feed" ? 160 : 107;
    image.loading = "lazy";
    figure.appendChild(image);
    const body = document.createElement("div");
    body.className = "rc-body";
    const label = document.createElement("span");
    label.className = "rc-label";
    label.textContent = card.topline;
    const title = document.createElement("span");
    title.className = "rc-title";
    title.textContent = card.title;
    const source = document.createElement("span");
    source.className = "rc-source";
    source.textContent = card.source;
    body.append(label, title, source);
    link.append(figure, body);
    element.appendChild(link);
    return element;
}

export function createFrame(placement, kind, index) {
    const frame = document.createElement("iframe");
    frame.className = "rc-frame";
    frame.title = kind === "unit" ? "Videoeinheit" : "Messung";
    frame.setAttribute("aria-hidden", "true");
    frame.tabIndex = -1;
    frame.width = "0";
    frame.height = "0";
    const message = JSON.stringify({ tpReco: { placement, kind, index } });
    frame.srcdoc = `<!doctype html><meta charset="utf-8"><title>${kind}</title><body style="margin:0"><script>parent.postMessage(${message},"*")<\/script></body>`;
    return frame;
}
